-- 2 champion fight(s) (LaunchBOS)
-- arena 1: setup SetUp, warm-up WarmUp, combat Combat, won BOS2, lost BoS_Lost, time-out BOS2
if SetUp ~= nil then Coop_Orig.SetUp = SetUp
	function SetUp(a1, a2, a3) Coop_BOS_Setup(1) Coop_AllowMove = true Coop_Orig.SetUp(a1, a2, a3) Coop_BOS_BringPlayers() Coop_AllowMove = false end end
if Combat ~= nil then Coop_Orig.Combat = Combat
	function Combat(a1, a2, a3) if Coop_BOS_Combat(1) then return Coop_Orig.Combat(a1, a2, a3) end end end
if BOS2 ~= nil then Coop_Orig.BOS2 = BOS2
	function BOS2(a1, a2, a3) if Coop_BOS_Won(1) then return Coop_Orig.BOS2(a1, a2, a3) end end end
if BoS_Lost ~= nil then Coop_Orig.BoS_Lost = BoS_Lost
	function BoS_Lost(a1, a2, a3) if Coop_BOS_IsDone(1) then PrintDebug("[coop] BoS_Lost after the fight was won - ignored") return end return Coop_Orig.BoS_Lost(a1, a2, a3) end end
-- arena 0: setup BoS_Setup, warm-up BoS_WarmUp, combat CombatBOS, won BOS_End, lost BoS_Lost, time-out BOS_End
if BoS_Setup ~= nil then Coop_Orig.BoS_Setup = BoS_Setup
	function BoS_Setup(a1, a2, a3) Coop_BOS_Setup(0) Coop_AllowMove = true Coop_Orig.BoS_Setup(a1, a2, a3) Coop_BOS_BringPlayers() Coop_AllowMove = false end end
if CombatBOS ~= nil then Coop_Orig.CombatBOS = CombatBOS
	function CombatBOS(a1, a2, a3) if Coop_BOS_Combat(0) then return Coop_Orig.CombatBOS(a1, a2, a3) end end end
if BOS_End ~= nil then Coop_Orig.BOS_End = BOS_End
	function BOS_End(a1, a2, a3) if Coop_BOS_Won(0) then return Coop_Orig.BOS_End(a1, a2, a3) end end end

-- the engine never ends a fight when the champion dies in MP: Coop_Tick (host, 1/s) does
function Coop_LevelTick()
	if BOS2 ~= nil and Coop_BOS_ChampionDead(1) then PrintDebug("[coop] champion of arena 1 is dead - BOS2") BOS2() end
	if BOS_End ~= nil and Coop_BOS_ChampionDead(0) then PrintDebug("[coop] champion of arena 0 is dead - BOS_End") BOS_End() end
end
-- UpdateLevel waits for InitLevel (coop_mission.lua sets Coop_LevelReady right before it)
Coop_LevelReady = false
-- dialogue is spoken in this level (coop_mission.lua; COOP_Patrol sets true to skip it)
Coop_SkipDialogue = false
if UpdateLevel ~= nil then Coop_Orig.UpdateLevel = UpdateLevel
	function UpdateLevel(a1, a2, a3) if Coop_LevelReady then return Coop_Orig.UpdateLevel(a1, a2, a3) end end end
PrintDebug("[coop] COOP_Cargo_Bay_1 co-op script loaded: 47 trigger(s), 2 champion fight(s)")
